<?php
/** @var string $base @var string $csrf @var array $tickets @var array $invoices @var array $categories @var array $statuses @var string $statusFilter @var int $page @var int $pageCount @var int $total @var int $unreadCount */
$e = static fn($value): string => htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
$statusTones = ['open'=>'primary','in_progress'=>'info','waiting_owner'=>'warning','resolved'=>'success'];
?>
<div class="alert alert-light border d-flex justify-content-between align-items-center"><span>Gunakan tiket untuk kendala teknis, pembayaran, akun, atau pertanyaan lain.</span><span class="badge text-bg-primary"><?= number_format($unreadCount,0,',','.') ?> balasan baru</span></div>
<div class="row g-3">
  <aside class="col-xl-4"><form method="post" action="<?= $e($base) ?>/owner/support/tickets" class="card"><div class="card-header"><strong>Buat tiket bantuan</strong><div class="small text-muted">Balasan tersimpan di halaman ini.</div></div><div class="card-body">
    <input type="hidden" name="_csrf" value="<?= $e($csrf) ?>">
    <div class="mb-3"><label class="form-label small fw-semibold" for="ticketCategory">Kategori</label><select class="form-select" id="ticketCategory" name="category" required><?php foreach ($categories as $key=>$label): ?><option value="<?= $e($key) ?>"><?= $e($label) ?></option><?php endforeach; ?></select></div>
    <div class="mb-3"><label class="form-label small fw-semibold" for="ticketSubject">Subjek</label><input class="form-control" id="ticketSubject" name="subject" minlength="5" maxlength="150" required placeholder="Ringkas masalahnya"></div>
    <div class="mb-3"><label class="form-label small fw-semibold" for="ticketInvoice">Invoice terkait (opsional)</label><select class="form-select" id="ticketInvoice" name="invoice_id"><option value="">Tidak terkait invoice</option><?php foreach ($invoices as $invoice): ?><option value="<?= (int)$invoice['id'] ?>"><?= $e($invoice['invoice_no']) ?> · <?= $e($invoice['status']) ?> · Rp<?= number_format((float)$invoice['amount'],0,',','.') ?></option><?php endforeach; ?></select></div>
    <div class="mb-3"><label class="form-label small fw-semibold" for="ticketBody">Pesan</label><textarea class="form-control" id="ticketBody" name="body" rows="5" minlength="10" maxlength="5000" required placeholder="Jelaskan kendala dan langkah yang sudah dicoba."></textarea><div class="form-text">Jangan tulis kata sandi, PIN, atau data kartu pembayaran.</div></div>
    <button class="btn btn-primary w-100" type="submit">Kirim tiket</button>
  </div></form></aside>
  <section class="col-xl-8"><div class="card"><div class="card-header d-flex flex-wrap justify-content-between align-items-center gap-2"><div><strong>Tiket saya</strong><div class="small text-muted"><?= number_format($total,0,',','.') ?> tiket</div></div><form method="get" action="<?= $e($base) ?>/owner/support" class="d-flex gap-2"><label class="visually-hidden" for="ticketStatus">Filter status</label><select class="form-select form-select-sm" id="ticketStatus" name="status"><option value="">Semua status</option><?php foreach ($statuses as $key=>$label): ?><option value="<?= $e($key) ?>" <?= $statusFilter===$key?'selected':'' ?>><?= $e($label) ?></option><?php endforeach; ?></select><button class="btn btn-outline-primary btn-sm">Filter</button></form></div>
    <div class="list-group list-group-flush">
      <?php foreach ($tickets as $ticket): $unread = $ticket['last_message_at'] > ($ticket['owner_read_at'] ?? '1970-01-01 00:00:00'); ?>
        <a class="list-group-item list-group-item-action p-3" href="<?= $e($base) ?>/owner/support/ticket?id=<?= (int)$ticket['id'] ?>"><div class="d-flex justify-content-between gap-2"><div class="min-w-0"><strong class="d-block text-truncate"><?= $e($ticket['subject']) ?></strong><span class="small text-muted">#<?= $e($ticket['ticket_no']) ?> · <?= $e($categories[$ticket['category']] ?? $ticket['category']) ?> · <?= $e($ticket['tenant_name']) ?></span><div class="small text-muted text-truncate mt-1"><?= $e($ticket['last_message'] ?? '') ?></div></div><div class="text-end flex-shrink-0"><span class="badge text-bg-<?= $e($statusTones[$ticket['status']] ?? 'secondary') ?>"><?= $e($statuses[$ticket['status']] ?? $ticket['status']) ?></span><?php if ($unread && $ticket['last_sender_role']==='super_admin'): ?><div class="small text-primary fw-semibold mt-1">Balasan baru</div><?php endif; ?><div class="small text-muted mt-1"><?= $e(date('d M, H:i',strtotime((string)$ticket['last_message_at']))) ?></div></div></div></a>
      <?php endforeach; ?>
      <?php if (!$tickets): ?><div class="text-center text-muted py-5">Belum ada tiket pada filter ini.</div><?php endif; ?>
    </div>
    <div class="card-footer d-flex justify-content-between align-items-center"><span class="small">Halaman <?= $page ?> dari <?= $pageCount ?></span><div class="d-flex gap-2"><?php if($page>1): ?><a class="btn btn-outline-secondary btn-sm" href="<?= $e($base) ?>/owner/support?<?= $e(http_build_query(['status'=>$statusFilter,'page'=>$page-1])) ?>">Sebelumnya</a><?php endif; ?><?php if($page<$pageCount): ?><a class="btn btn-outline-secondary btn-sm" href="<?= $e($base) ?>/owner/support?<?= $e(http_build_query(['status'=>$statusFilter,'page'=>$page+1])) ?>">Berikutnya</a><?php endif; ?></div></div>
  </div></section>
</div>